<script lang="ts">
 import {t} from '#lib/i18n.ts';
 import {session,api,refreshSession} from '#lib/client.svelte.ts';import Icon from '#lib/components/Icon.svelte';import {goto} from '$app/navigation';import {page} from '$app/state';
 let mode=$state('register');let username=$state('');let password=$state('');let error=$state('');let busy=$state(false);
 async function submit(){busy=true;error='';try{await api('auth/'+mode,{username,password});await refreshSession();const next=page.url.searchParams.get('next');await goto(next?.startsWith('/')&&!next.startsWith('//')?next:'/notizen');}catch(e){error=(e as Error).message;}busy=false;}
 async function logout(){busy=true;try{await api('auth/logout',{});await refreshSession();password='';}catch(e){error=(e as Error).message;}busy=false;}
 function exportData(){const blob=new Blob([JSON.stringify({username:session.user?.username,notes:session.notes},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sip-happens-notizen.json';a.click();URL.revokeObjectURL(a.href);}
</script>
<svelte:head><title>{t('m_05e0ddc9ba')}</title></svelte:head>
<div class="page-content"><div class="page-heading"><div><div class="eyebrow">{t('m_356df9e22a')}</div><h1>{session.user?'Hallo, '+session.user.username:'Schön, wenn du bleibst'}<span class="accent">.</span></h1><p>{session.user?'Deine Notizen und dein Keller sind hier zu Hause.':'Nur ein Username und ein Passwort. Deine Tasting-Notizen kommen mit.'}</p></div></div>{#if session.user}<div class="panel" style="max-width:620px"><h2>{t('m_693a2279c5')}</h2><p>{t('m_15fd736319')} <strong>{session.user.username}</strong> {t('m_87fab41efc')}</p><div class="export-row"><a class="button primary" href="/notizen">{t('m_f6787ed161')}<Icon name="right" size={17}/></a><a class="button outline" href="/keller">{t('m_dcff627388')}</a></div><button class="text-button" onclick={logout} disabled={busy}><Icon name="logout" size={16}/>{t('m_7e324c5c00')}</button></div>{:else}<div class="account-layout"><div class="panel"><div class="filters" style="margin-top:0"><button class="filter" class:active={mode==='register'} onclick={()=>{mode='register';error='';}}>{t('m_75fe43e7f3')}</button><button class="filter" class:active={mode==='login'} onclick={()=>{mode='login';error='';}}>{t('m_a13480ab17')}</button></div><h2>{mode==='register'?'Ein kleines Konto für deine Weine.':'Willkommen zurück.'}</h2><form onsubmit={(e)=>{e.preventDefault();submit();}}><label>{t('m_84c29015de')}<input aria-label={t('m_84c29015de')} bind:value={username} required minlength="3" maxlength="24" autocomplete="username" placeholder={t('m_a60375629b')}/><small class="muted" style="font-weight:400;font-size:9px">{t('m_94fa66d6b3')}</small></label><label>{t('m_0719708d1c')}<input type="password" bind:value={password} required minlength="10" maxlength="128" autocomplete={mode==='register'?'new-password':'current-password'} placeholder={t('m_5a193aa3dc')}/></label>{#if mode==='register'}<div class="callout"><Icon name="help" size={17}/><p>{t('m_cb9edb2c30')}</p></div>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="button primary full" disabled={busy}>{busy?'Einen Moment …':mode==='register'?'Konto anlegen & Notizen behalten':'Anmelden'}<Icon name="right" size={17}/></button></form></div><aside class="account-perks"><Icon name="wine" size={32}/><h2>{t('m_0a6fffa95f')}<br/>{t('m_ca91d698be')}</h2><p>{t('m_20b68b1719')}</p><div class="perk"><Icon name="notes"/><div><strong>{t('m_d2f699cb97')}</strong><p>{t('m_87d445fe84')}</p></div></div><div class="perk"><Icon name="cellar"/><div><strong>{t('m_b63b0f221e')}</strong><p>{t('m_0c0a7c0dfe')}</p></div></div><div class="perk"><Icon name="compass"/><div><strong>{t('m_fed8b644a4')}</strong><p>{t('m_5f1210024c')}</p></div></div></aside></div>{/if}<section class="data-info" id="daten"><h2>{t('m_287f1db0af')}</h2><p>{t('m_0d6259a51e')}</p><p>{t('m_526d9703b0')}</p><p>{t('m_e007ef512c')}</p><div class="export-row"><button class="button outline" onclick={exportData}><Icon name="download" size={16}/>{t('m_933fd0bbf9')}</button></div></section></div>
